{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'fs'
import { stdin } from 'process'

// ============================================================================
// Error Handling
// ============================================================================

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function lineError(lineNum, reason) {
  process.stderr.write(`error: line ${lineNum}: ${reason}\n`)
  process.exit(2)
}

// ============================================================================
// Validation
// ============================================================================

const VALID_NAME_CHARS = /^[A-Za-z0-9_./:_-]+$/

function isValidName(name) {
  return VALID_NAME_CHARS.test(name) && name.length > 0
}

function parseUnsignedInt(str, fieldName, minimum, lineNum) {
  if (!/^\d+$/.test(str)) {
    lineError(lineNum, `${fieldName} must be an integer of at least ${minimum}`)
  }
  const num = parseInt(str, 10)
  if (num < minimum) {
    lineError(lineNum, `${fieldName} must be an integer of at least ${minimum}`)
  }
  return num
}

// ============================================================================
// Policies
// ============================================================================

class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map() // key -> { tokens, lastTick }
  }

  initialize(key, tick) {
    if (!this.states.has(key)) {
      this.states.set(key, { tokens: this.capacity, lastTick: tick })
    }
  }

  advance(key, tick) {
    this.initialize(key, tick)
    const state = this.states.get(key)
    const ticksPassed = tick - state.lastTick
    // Add refill * ticksPassed / per tokens (exact fractional arithmetic)
    // We'll store the numerator and denominator and track exact fractions
    if (ticksPassed > 0) {
      const tokensToAdd = (this.refill * ticksPassed) / this.per
      state.tokens = Math.min(state.capacity, state.tokens + tokensToAdd)
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.tokens >= 1
  }

  record(key) {
    const state = this.states.get(key)
    state.tokens -= 1
  }
}

class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map() // key -> Set of ticks
  }

  advance(key, tick) {
    if (!this.states.has(key)) {
      this.states.set(key, new Set())
    }
    const ticks = this.states.get(key)
    // Forget ticks at or before (tick - span)
    const cutoff = tick - this.span
    for (const t of ticks) {
      if (t <= cutoff) {
        ticks.delete(t)
      }
    }
  }

  allow(key) {
    const ticks = this.states.get(key)
    return ticks.size < this.limit
  }

  record(key, tick) {
    const ticks = this.states.get(key)
    ticks.add(tick)
  }
}

// ============================================================================
// Parser
// ============================================================================

function parseInput(lines) {
  const buckets = new Map()
  const windows = new Map()
  const routes = []
  const events = []
  let firstEventLine = -1
  let lastTick = -1

  for (let i = 0; i < lines.length; i++) {
    let line = lines[i]
    // Trim and skip empty/comment lines
    line = line.trim()
    if (!line || line.startsWith('#')) {
      continue
    }

    const lineNum = i + 1
    const parts = line.split(/\s+/)

    const directive = parts[0]

    if (directive === 'bucket') {
      if (firstEventLine >= 0) {
        lineError(lineNum, 'declarations must come before the first event')
      }
      if (parts.length !== 5) {
        lineError(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityStr, refillStr, perStr] = parts
      if (!isValidName(name)) {
        lineError(lineNum, `invalid policy name ${name}`)
      }
      if (buckets.has(name) || windows.has(name)) {
        lineError(lineNum, `policy ${name} is declared twice`)
      }
      const capacity = parseUnsignedInt(capacityStr, 'capacity', 1, lineNum)
      const refill = parseUnsignedInt(refillStr, 'refill', 0, lineNum)
      const per = parseUnsignedInt(perStr, 'per', 1, lineNum)
      buckets.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (firstEventLine >= 0) {
        lineError(lineNum, 'declarations must come before the first event')
      }
      if (parts.length !== 4) {
        lineError(lineNum, 'expected window <name> <limit> <span>')
      }
      const [, name, limitStr, spanStr] = parts
      if (!isValidName(name)) {
        lineError(lineNum, `invalid policy name ${name}`)
      }
      if (buckets.has(name) || windows.has(name)) {
        lineError(lineNum, `policy ${name} is declared twice`)
      }
      const limit = parseUnsignedInt(limitStr, 'limit', 0, lineNum)
      const span = parseUnsignedInt(spanStr, 'span', 1, lineNum)
      windows.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (firstEventLine >= 0) {
        lineError(lineNum, 'declarations must come before the first event')
      }
      if (parts.length < 3) {
        lineError(lineNum, 'expected route <prefix> <policy>...')
      }
      const prefix = parts[1]
      if (!isValidName(prefix)) {
        lineError(lineNum, `invalid route prefix ${prefix}`)
      }
      // Check for duplicate prefix
      for (const route of routes) {
        if (route.prefix === prefix) {
          lineError(lineNum, `prefix ${prefix} is routed twice`)
        }
      }
      const policyNames = parts.slice(2)
      const policies = []
      for (const policyName of policyNames) {
        if (buckets.has(policyName)) {
          policies.push(buckets.get(policyName))
        } else if (windows.has(policyName)) {
          policies.push(windows.get(policyName))
        } else {
          lineError(lineNum, `unknown policy ${policyName}`)
        }
      }
      routes.push({ prefix, policyNames, policies })
    } else if (directive === 'event') {
      if (firstEventLine < 0) {
        firstEventLine = lineNum
      }
      if (parts.length !== 3) {
        lineError(lineNum, 'expected event <tick> <key>')
      }
      const [, tickStr, key] = parts
      const tick = parseUnsignedInt(tickStr, 'tick', 0, lineNum)
      if (!isValidName(key)) {
        lineError(lineNum, `invalid key ${key}`)
      }
      if (tick < lastTick) {
        lineError(lineNum, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key, lineNum })
    } else {
      lineError(lineNum, `unknown directive ${directive}`)
    }
  }

  return { buckets, windows, routes, events }
}

// ============================================================================
// Event Processing
// ============================================================================

function findRoute(key, routes) {
  let bestRoute = null
  let bestPrefixLength = -1
  for (const route of routes) {
    if (key.startsWith(route.prefix) && route.prefix.length > bestPrefixLength) {
      bestRoute = route
      bestPrefixLength = route.prefix.length
    }
  }
  return bestRoute
}

function processEvents(routes, events) {
  const results = []
  const keyStats = new Map() // key -> { allowed, denied }

  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(key, routes)

    if (!route) {
      // No route matches, always allow
      results.push({ tick, key, allowed: true, deniedBy: null })
      if (!keyStats.has(key)) {
        keyStats.set(key, { allowed: 0, denied: 0 })
      }
      keyStats.get(key).allowed++
    } else {
      // Advance all policies to this tick
      for (const policy of route.policies) {
        policy.advance(key, tick)
      }

      // Check if all policies allow
      let deniedBy = null
      for (let i = 0; i < route.policies.length; i++) {
        if (!route.policies[i].allow(key)) {
          deniedBy = route.policyNames[i]
          break
        }
      }

      if (deniedBy === null) {
        // All allow, record on all policies
        for (const policy of route.policies) {
          if (policy instanceof TokenBucket) {
            policy.record(key)
          } else {
            policy.record(key, tick)
          }
        }
        results.push({ tick, key, allowed: true, deniedBy: null })
        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 })
        }
        keyStats.get(key).allowed++
      } else {
        // Denied, don't record
        results.push({ tick, key, allowed: false, deniedBy })
        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 })
        }
        keyStats.get(key).denied++
      }
    }
  }

  return { results, keyStats }
}

// ============================================================================
// Output
// ============================================================================

function outputReplay(results) {
  for (const result of results) {
    if (result.allowed) {
      process.stdout.write(`${result.tick} ${result.key} allow\n`)
    } else {
      process.stdout.write(`${result.tick} ${result.key} deny ${result.deniedBy}\n`)
    }
  }
}

function outputSummary(keyStats) {
  const sortedKeys = Array.from(keyStats.keys()).sort()
  let totalAllowed = 0
  let totalDenied = 0

  for (const key of sortedKeys) {
    const stats = keyStats.get(key)
    process.stdout.write(`${key} allowed=${stats.allowed} denied=${stats.denied}\n`)
    totalAllowed += stats.allowed
    totalDenied += stats.denied
  }

  process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
}

// ============================================================================
// Main
// ============================================================================

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError()
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (e) {
    // stdin is empty
    input = ''
  }

  // Split into lines and drop trailing empty line
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  // Parse
  const { buckets, windows, routes, events } = parseInput(lines)

  // Process events
  const { results, keyStats } = processEvents(routes, events)

  // Output
  if (mode === 'replay') {
    outputReplay(results)
  } else {
    outputSummary(keyStats)
  }
}

main()
"}

