        lineError(lineNum, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      events.push({ tick, key, lineNum })
    } else {
      lineError(lineNum, `unknown directive ${directive}`)
    }
  }

  return { buckets, windows, routes, events }
}

// ============================================================================
// Event Processing
// ============================================================================

function findRoute(key, routes) {
  let bestRoute = null
  let bestPrefixLength = -1
  for (const route of routes) {
    if (key.startsWith(route.prefix) && route.prefix.length > bestPrefixLength) {
      bestRoute = route
      bestPrefixLength = route.prefix.length
    }
  }
  return bestRoute
}

function processEvents(routes, events) {
  const results = []
  const keyStats = new Map() // key -> { allowed, denied }

  for (const event of events) {
    const { tick, key } = event
    const route = findRoute(key, routes)

    if (!route) {
      // No route matches, always allow
      results.push({ tick, key, allowed: true, deniedBy: null })
      if (!keyStats.has(key)) {
        keyStats.set(key, { allowed: 0, denied: 0 })
      }
      keyStats.get(key).allowed++
    } else {
      // Advance all policies to this tick
      for (const policy of route.policies) {
        policy.advance(key, tick)
      }

      // Check if all policies allow
      let deniedBy = null
      for (let i = 0; i < route.policies.length; i++) {
        if (!route.policies[i].allow(key)) {
          deniedBy = route.policyNames[i]
          break
        }
      }

      if (deniedBy === null) {
        // All allow, record on all policies
        for (const policy of route.policies) {
          if (policy instanceof TokenBucket) {
            policy.record(key)
          } else {
            policy.record(key, tick)
          }
        }
        results.push({ tick, key, allowed: true, deniedBy: null })
        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 })
        }
        keyStats.get(key).allowed++
      } else {
        // Denied, don't record
        results.push({ tick, key, allowed: false, deniedBy })
        if (!keyStats.has(key)) {
          keyStats.set(key, { allowed: 0, denied: 0 })
        }
        keyStats.get(key).denied++
      }
    }
  }

  return { results, keyStats }
}

// ============================================================================
// Output
// ============================================================================

function outputReplay(results) {
  for (const result of results) {
    if (result.allowed) {
      process.stdout.write(`${result.tick} ${result.key} allow\n`)
    } else {
      process.stdout.write(`${result.tick} ${result.key} deny ${result.deniedBy}\n`)
    }
  }
}

function outputSummary(keyStats) {
  const sortedKeys = Array.from(keyStats.keys()).sort()
  let totalAllowed = 0
  let totalDenied = 0

  for (const key of sortedKeys) {
    const stats = keyStats.get(key)
    process.stdout.write(`${key} allowed=${stats.allowed} denied=${stats.denied}\n`)
    totalAllowed += stats.allowed
    totalDenied += stats.denied
  }

  process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
}

// ============================================================================
// Main
// ============================================================================

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError()
  }

  const mode = args[0]

  // Read stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (e) {
    // stdin is empty
    input = ''
  }

  // Split into lines and drop trailing empty line
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  // Parse
  const { buckets, windows, routes, events } = parseInput(lines)

  // Process events
  const { results, keyStats } = processEvents(routes, events)

  // Output
  if (mode === 'replay') {
    outputReplay(results)
  } else {
    outputSummary(keyStats)
  }
}

main()

