{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e5-handoff-drop-t5/cell-JnMElY/src/policies.js","content":"/**
 * The rate limiting policies. Each keeps one independent state per key.
 * All arithmetic is exact: token counts are kept as a numerator over the
 * bucket's period, and ticks are BigInt so arbitrarily large values work.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // tokens are stored as a numerator over `per`
    this.full = capacity * per
    this.states = new Map() // key -> { num, lastTick }
  }

  state(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { num: this.full, lastTick: tick }
      this.states.set(key, state)
    }
    return state
