 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function routeFor(routes, key) {
  let best = null
  for (const route of routes) {
    if (!key.startsWith(route.prefix)) continue
    if (best === null || route.prefix.length > best.prefix.length) best = route
  }
  return best
}

function simulate(routes, events) {
  const verdicts = []
  for (const { tick, key } of events) {
    const route = routeFor(routes, key)
    let refused = null
    if (route !== null) {
      for (const policy of route.policies) policy.advance(key, tick)
      for (const policy of route.policies) {
        if (!policy.allows(key, tick)) {
          refused = policy.name
          break
        }
      }
      if (refused === null) {
        for (const policy of route.policies) policy.record(key, tick)
      }
    }
    verdicts.push({ tick, key, refused })
  }
  return verdicts
}

function replay(verdicts) {
  let out = ''
  for (const { tick, key, refused } of verdicts) {
    out += refused === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${refused}\n`
  }
  return out
}

function summary(verdicts) {
  const counts = new Map()
  let allowed = 0
  let denied = 0
  for (const { key, refused } of verdicts) {
    let entry = counts.get(key)
    if (entry === undefined) {
      entry = { allowed: 0, denied: 0 }
      counts.set(key, entry)
    }
    if (refused === null) {
      entry.allowed++
      allowed++
    } else {
      entry.denied++
      denied++
    }
  }
  let out = ''
  for (const key of [...counts.keys()].sort()) {
    const entry = counts.get(key)
    out += `${key} allowed=${entry.allowed} denied=${entry.denied}\n`
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}

function main() {
  const argv = process.argv.slice(2)
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'replay' && mode !== 'summary') fail('usage: cli.js replay|summary')

  let parsed
  try {
    parsed = parse(readStdin())
  } catch (error) {
    if (error instanceof ParseError) fail(error.message)
    throw error
  }

  const verdicts = simulate(parsed.routes, parsed.events)
  process.stdout.write(mode === 'replay' ? replay(verdicts) : summary(verdicts))
}

main()
